// packages/api/src/services/historico.js
import { Router }       from 'express';
import { BaseService }  from './_baseService.js';
import { HistoricoDTO } from '../dto/historico.js';

export class HistoricoService {
    static router() {
        const r = Router();
        r.get('/',    HistoricoService.#listar);
        r.get('/:id', HistoricoService.#obter);
        // Historico é imutável — sem POST, PUT, DELETE
        return r;
    }

    // ── GET /api/historico?page=1&pageSize=20&userID=...&catalogoID=... ────────
    static #listar = async (req, res) => {
        try {
            const { page = 1, pageSize = 20, userID, catalogoID, tipo, acao } = req.query;
            const offset = (Number(page) - 1) * Number(pageSize);

            const where  = ['1=1'];
            const params = [];

            if (userID)     { where.push('userID = ?');     params.push(userID);     }
            if (catalogoID) { where.push('catalogoID = ?'); params.push(catalogoID); }
            if (tipo)       { where.push('tipo = ?');       params.push(tipo);       }
            if (acao)       { where.push('acao = ?');       params.push(acao);       }

            const whereClause = where.join(' AND ');

            const [rows, countRow] = await Promise.all([
                BaseService.query(req.db,
                    `SELECT * FROM historico
                     WHERE ${whereClause}
                     ORDER BY dataHora DESC LIMIT ? OFFSET ?`,
                    [...params, Number(pageSize), offset]),
                BaseService.queryOne(req.db,
                    `SELECT COUNT(*) as total FROM historico WHERE ${whereClause}`,
                    params)
            ]);

            return BaseService.ok(res, HistoricoDTO.fromRows(rows), {
                page        : Number(page),
                pageSize    : Number(pageSize),
                totalRecords: countRow.total,
                totalPages  : Math.ceil(countRow.total / Number(pageSize))
            });
        } catch (e) { return HistoricoService.#erro(res, e); }
    };

    // ── GET /api/historico/:id ────────────────────────────────────────────────
    static #obter = async (req, res) => {
        try {
            const row = await BaseService.queryOne(req.db,
                `SELECT * FROM historico WHERE id = ?`,
                [req.params.id]);
            if (!row) return BaseService.fail(res, 'Evento não encontrado.', 404);
            return BaseService.ok(res, HistoricoDTO.fromRow(row));
        } catch (e) { return HistoricoService.#erro(res, e); }
    };

    // ── Error handler local ───────────────────────────────────────────────────
    static #erro(res, e) {
        console.error(`[${BaseService.now()}] [HistoricoService]`, e.message);
        return BaseService.fail(res, 'Erro interno do servidor.', 500);
    }
}